/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import subprocess
p=Path('tests/pause-motion.test.ts');s=p.read_text();s+='''

test('pause retraction preserves a parked button at its authored twip coordinate', () => {
  const motion = new PauseMotion();
  motion.phase = 'info';
  motion.advance();
  expect(motion.positions.btn5_mc.x).toBe(643.9);
});
''';p.write_text(s)
p=Path('src/game/core/pause-motion.ts');original=p.read_text();assert '0.9 : 0.93' in original
try:
 p.write_text(original.replace('0.9 : 0.93','0.9 : (1 - 0.07)'))
 with Path('/tmp/bt3-pause-park-red.log').open('w') as log:
  r=subprocess.run(['bun','test','tests/pause-motion.test.ts','-t','parked button'],stdout=log,stderr=subprocess.STDOUT)
 print('derived-coefficient regression exit:',r.returncode)
finally:p.write_text(original)
PY
bun run format >/tmp/bt3-pause-model-format.log 2>&1 && bun run check >/tmp/bt3-pause-model-check.log 2>&1 && git diff --check && git diff HEAD --stat"
